-- Mois 2 (jours 31 à 60) du programme HABITUDES_DEFIS_30J_FR_V1, version 1 : remplace la reprise des 30 textes du mois 1.
-- Textes validés par Dr Justin Tshims le 27/10/2026 (« C'est bon pour les textes du mois 2 »). Généré depuis
-- editorial/habitudes-defis/mois-2-fr-relecture.md. Aucune inscription n'avait encore atteint le jour 31 : les textes
-- déjà servis (jours 1 à 30) ne changent pas. Activités, défis et horaires inchangés.
do $$begin
 if exists(select 1 from seneve.enrollments e where e.programme_id='HABITUDES_DEFIS_30J_FR_V1' and e.etat='active'
  and seneve.hd_date_du_jour(e.enrollment_id,31)<=(now()at time zone 'Africa/Kinshasa')::date)then
  raise exception 'Une inscription a déjà atteint le jour 31 : publier une nouvelle version plutôt que modifier celle-ci';
 end if;
 if (select count(*)from seneve.contents where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour between 31 and 60 and numero_message=1)<>30 then
  raise exception 'Jours 31 à 60 incomplets';
 end if;
end$$;
update seneve.contents set titre=$t$Regarder qui est premier$t$,principe=$t$Observer honnêtement ce qui occupe la première place.$t$,theme=$t$Qu'est-ce qui a reçu tes premières minutes ce matin ?$t$,texte_officiel=$t$Le livre s'ouvre sur une seule question : « Qui est vraiment premier dans ta vie ? » Il ne s'agit pas de ce que tu chantes le dimanche, mais de ce que montrent tes décisions, ton agenda et ton argent. Aujourd'hui, observe simplement ta journée, sans te juger. Où vont tes premières minutes, tes premières pensées, tes premières dépenses ? Ce regard honnête n'est pas une note : c'est un point de départ pour remettre de l'ordre, pas à pas.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 9–10.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=31 and numero_message=1;
update seneve.contents set titre=$t$Roi ou assistant$t$,principe=$t$Passer de « bénis mon projet » à « que veux-Tu que je fasse ? ».$t$,theme=$t$Quelle décision veux-tu présenter à Dieu avant de la prendre ?$t$,texte_officiel=$t$Le livre distingue deux prières. L'une dit : « Seigneur, bénis ce que je fais. » L'autre demande : « Seigneur, que veux-Tu que je fasse ? » La première a déjà tout décidé ; la seconde attend une direction. L'histoire de Simon, au chapitre 1, montre ce qui arrive quand l'intelligence devient roi et Dieu un simple assistant. Choisis une décision de ta journée et présente-la à Dieu avant de la prendre, avec tes propres mots.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 18–20.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=32 and numero_message=1;
update seneve.contents set titre=$t$Confier son agenda$t$,principe=$t$Relier le temps de prière au reste de la journée.$t$,theme=$t$Quel moment de ta journée as-tu le plus de mal à confier à Dieu ?$t$,texte_officiel=$t$Le livre met en garde contre une idée confortable : avoir prié le matin suffirait à rendre Dieu premier. Il propose une autre image : « le vrai chrétien ne met pas Dieu dans son agenda — il met son agenda dans les mains de Dieu. » Ton temps de prière reste précieux ; il peut aussi devenir le moment où tu regardes ta journée avec Lui. « Reconnais-Le dans toutes tes voies » (Proverbes 3:6). Avant de commencer tes activités, relis ton programme dans la prière.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 21–23.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=33 and numero_message=1;
update seneve.contents set titre=$t$Mettre de l'ordre dans ses priorités$t$,principe=$t$Se situer dans l'ordre des priorités proposé par le livre.$t$,theme=$t$Quel domaine de ta vie mérite plus d'attention cette semaine ?$t$,texte_officiel=$t$Le chapitre 1 propose un ordre : Dieu, ta vie spirituelle personnelle, ton foyer, ton travail ou tes études, ton service dans l'église, puis le reste. Il rappelle que le foyer passe avant les activités d'église (1 Timothée 3:4-5). Regarde ta semaine à la lumière de cet ordre. Il ne s'agit pas de tout bouleverser d'un coup, mais de repérer un domaine qui a pris trop de place, ou pas assez.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 29–31.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=34 and numero_message=1;
update seneve.contents set titre=$t$La première part plutôt que les restes$t$,principe=$t$Comprendre l'idée de « prémices ».$t$,theme=$t$À quel moment mets-tu de côté ce que tu donnes à Dieu ?$t$,texte_officiel=$t$Le livre raconte l'histoire de frère Évariste, qui calculait sa dîme sur ce qui restait après toutes ses charges — souvent rien. Le chapitre 2 rappelle Proverbes 3:9 : honorer l'Éternel « avec les prémices de tout ton revenu », c'est-à-dire la première part, pas les restes. Si tu pratiques la dîme, observe à quel moment tu la mets de côté. Le simulateur facultatif du module peut t'aider à faire le calcul ; il n'enregistre rien et ne déclenche aucun paiement.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 39–41 ; enseignement complémentaire sur la dîme validé par Dr Justin (cahier Habitudes & Défis, section 8).$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=35 and numero_message=1;
update seneve.contents set titre=$t$Distinguer la dîme et l'offrande$t$,principe=$t$Différencier ce qui est rendu et ce qui est offert.$t$,theme=$t$Qu'est-ce qui rend un don vraiment libre pour toi ?$t$,texte_officiel=$t$Le livre distingue deux gestes. La dîme est une restitution : dix pour cent, rendus parce que cela appartient déjà à Dieu. L'offrande est un don libre, au-delà de la dîme, sans montant fixé. Jésus a remarqué la veuve qui avait donné deux petites pièces (Marc 12) : « Dieu pèse le sacrifice, pas le montant », écrit le livre. Aucun montant n'est attendu de toi ici. Réfléchis seulement à l'esprit dans lequel tu donnes.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 48–49.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=36 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : la première place$t$,principe=$t$Faire le point sur une semaine de priorités.$t$,theme=$t$Quel petit changement de priorité veux-tu garder la semaine prochaine ?$t$,texte_officiel=$t$Cette semaine a parlé de la première place : la question « qui est premier ? », la prière qui demande une direction, l'ordre des priorités et la première part de ce que tu reçois. Relis tes déclarations sans chercher un score. Note ce qui a changé, même légèrement, et ce qui reste difficile. Le livre le rappelle : Dieu ne cherche pas l'homme parfait, mais l'homme obéissant. Un ajustement modeste et tenu vaut mieux qu'une grande résolution abandonnée.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 33–34 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=37 and numero_message=1;
update seneve.contents set titre=$t$Donner sans chercher le regard$t$,principe=$t$Examiner ses motivations quand on donne.$t$,theme=$t$Lequel de ces trois pièges reconnais-tu le plus facilement en toi ?$t$,texte_officiel=$t$Le chapitre 2 décrit trois pièges qui vident un don de son sens : donner pour être vu, donner en murmurant, donner pour « forcer » Dieu. Jésus invite à donner sans que la main gauche sache ce que fait la droite (Matthieu 6:3). Paul rappelle que « Dieu aime celui qui donne avec joie » (2 Corinthiens 9:7). Le livre le dit nettement : on n'achète pas Dieu. Regarde lequel de ces pièges te guette le plus, sans t'accuser.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 50–51.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=38 and numero_message=1;
update seneve.contents set titre=$t$L'effort consacré$t$,principe=$t$Tenir ensemble le travail et la prière.$t$,theme=$t$Où penches-tu le plus : travailler sans prier, ou prier sans agir ?$t$,texte_officiel=$t$Le chapitre 3 décrit deux déséquilibres : travailler sans prier, et prier sans travailler. Le livre les résume par deux mots : « l'effort consacré ». L'effort, parce que tu agis ; consacré, parce que tu pries. Aujourd'hui, avant ton travail ou ta lecture professionnelle, confie ta tâche à Dieu en une phrase. Puis fais-la sérieusement, avec ce que tu as.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 58–59.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=39 and numero_message=1;
update seneve.contents set titre=$t$Le travail n'est pas une punition$t$,principe=$t$Regarder son travail comme une vocation.$t$,theme=$t$Quelle partie de ton travail as-tu tendance à mépriser ?$t$,texte_officiel=$t$Le livre rappelle que le travail existe avant la chute : Dieu place l'homme dans le jardin « pour le cultiver et pour le garder » (Genèse 2:15). Il rappelle aussi qu'à Nazareth, on appelait Jésus « le charpentier » (Marc 6:3). Aucun travail honnête n'est indigne. Que ton travail soit visible ou discret, payé ou non, regarde-le aujourd'hui comme une manière de servir.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 59–61.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=40 and numero_message=1;
update seneve.contents set titre=$t$Quand personne ne regarde$t$,principe=$t$Vérifier son intégrité dans les petits gestes du travail.$t$,theme=$t$Quel petit geste d'honnêteté peux-tu poser aujourd'hui au travail ?$t$,texte_officiel=$t$Le chapitre 3 parle de ce qui se passe au travail quand personne ne regarde : les heures déclarées, le matériel emprunté, le rapport arrangé. Il cite Daniel, chez qui ses adversaires ne trouvèrent « ni faute, ni rien de mauvais » (Daniel 6:4). Choisis aujourd'hui un petit geste d'honnêteté concret : corriger une erreur, rendre ce qui ne t'appartient pas, présenter un résultat tel qu'il est. Si quelque chose doit être réparé, fais-le simplement.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 64–67.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=41 and numero_message=1;
update seneve.contents set titre=$t$Ton travail parle avant toi$t$,principe=$t$Mesurer l'effet de son comportement sur les autres.$t$,theme=$t$Que voient tes collègues ou ta famille de ta foi dans ta manière de travailler ?$t$,texte_officiel=$t$Le livre affirme que « ta vie a déjà prêché avant ta bouche ». Arriver à l'heure, tenir sa parole, rendre la monnaie exacte, respecter les petits : ces gestes se remarquent. Ils peuvent ouvrir des conversations sans discours. Aujourd'hui, ne cherche pas à prêcher. Sois fiable dans une chose que les autres attendent de toi.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 73–74.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=42 and numero_message=1;
update seneve.contents set titre=$t$L'argent, un outil et non un maître$t$,principe=$t$Distinguer l'argent de l'attachement à l'argent.$t$,theme=$t$Combien de fois as-tu pensé à l'argent aujourd'hui, et dans quel état d'esprit ?$t$,texte_officiel=$t$Le chapitre 4 corrige une citation souvent mal faite : ce n'est pas l'argent, mais « l'amour de l'argent » qui est une racine de tous les maux (1 Timothée 6:10). L'argent est un outil ; l'attachement peut devenir une idole. Le livre note qu'on peut posséder beaucoup sans être possédé, et avoir peu tout en étant obsédé par l'argent. Regarde aujourd'hui la place que l'argent prend dans tes pensées, sans culpabilité.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 79–81.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=43 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : don, travail et argent$t$,principe=$t$Faire le point sur le don, le travail et l'argent.$t$,theme=$t$Quelle action simple veux-tu poursuivre la semaine prochaine ?$t$,texte_officiel=$t$Cette semaine a parlé de donner librement, de travailler avec prière et honnêteté, et de la place de l'argent. Relis ce que tu as déclaré, et ce que tu n'as pas pu faire, sans te juger. Si tu as remarqué un domaine à corriger, choisis une seule action simple pour la semaine prochaine. Si quelque chose te pèse, tu peux demander de l'aide à tout moment.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitres 2 à 4 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=44 and numero_message=1;
update seneve.contents set titre=$t$Quand la paix dépend du solde$t$,principe=$t$Repérer un signe d'attachement à l'argent.$t$,theme=$t$Lequel de ces signes reconnais-tu, même un peu, dans ta vie ?$t$,texte_officiel=$t$Le livre décrit plusieurs signes d'un cœur trop attaché à l'argent. Le premier : une paix qui monte et descend avec le compte. D'autres suivent : prier moins quand on gagne plus, faire des compromis pour protéger ce qu'on a, avoir du mal à donner, être dérangé par la réussite des autres. « Un seul suffit pour commencer le ménage », écrit-il. Choisis un signe et observe-le honnêtement aujourd'hui.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 81–83.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=45 and numero_message=1;
update seneve.contents set titre=$t$La gratitude contre la convoitise$t$,principe=$t$Pratiquer une gratitude précise.$t$,theme=$t$Quelles trois choses précises as-tu reçues aujourd'hui ?$t$,texte_officiel=$t$Le chapitre 4 propose un remède simple : chaque soir, nommer devant Dieu trois choses reçues dans la journée. « La gratitude est l'antidote naturel de la convoitise », écrit le livre. Ce soir, pendant ta gratitude, cherche des choses précises plutôt que générales : un repas, une parole, une aide, un moment de calme.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 88–89.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=46 and numero_message=1;
update seneve.contents set titre=$t$Des mains pleines mais ouvertes$t$,principe=$t$Réfléchir à ce que l'on retient.$t$,theme=$t$Qu'est-ce que tu aurais le plus de mal à remettre à Dieu ?$t$,texte_officiel=$t$Le livre compare deux hommes riches : Abraham, qui « se leva de bon matin » quand Dieu lui demanda Isaac (Genèse 22:3), et le jeune homme riche, qui repartit triste (Marc 10). Il souligne un détail : avant de parler, Jésus « l'aima ». Dieu ne cherche pas à prendre, mais à libérer. Ce n'est pas le montant qui compte, mais la capacité de lâcher. Pense à ce que tu tiens le plus fermement.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 89–92.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=47 and numero_message=1;
update seneve.contents set titre=$t$Choisir la simplicité$t$,principe=$t$Distinguer ses besoins de l'image que l'on veut donner.$t$,theme=$t$Laquelle de ces trois questions te concerne le plus aujourd'hui ?$t$,texte_officiel=$t$Le chapitre 4 parle d'une époque où l'on s'endette parfois pour paraître. Le livre précise que le luxe n'est pas un péché, mais que le besoin de paraître peut devenir une prison. Il propose trois questions : est-ce que j'achète pour mes besoins ou pour les regards ? Mon niveau de vie correspond-il à mes revenus réels ? Pourrais-je vivre plus simplement et donner davantage ? Prends le temps de répondre honnêtement à l'une d'elles.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 94–96.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=48 and numero_message=1;
update seneve.contents set titre=$t$Être un canal plutôt qu'un réservoir$t$,principe=$t$Comprendre la Tsedaka comme une justice.$t$,theme=$t$Ce que tu reçois circule-t-il vers d'autres, ou reste-t-il chez toi ?$t$,texte_officiel=$t$Le chapitre 5 présente le mot hébreu Tsedaka, qui signifie justice plutôt que charité. Le livre utilise une image : le réservoir garde l'eau jusqu'à ce qu'elle croupisse ; le canal la laisse passer et reste vivant. Aider ceux qui sont dans le besoin devient alors une manière juste de faire circuler ce que tu as reçu. Pense à une personne proche de toi qui traverse une difficulté.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 102–104.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=49 and numero_message=1;
update seneve.contents set titre=$t$Donner dans le secret$t$,principe=$t$Faire un geste de bonté sans le faire savoir.$t$,theme=$t$Quel geste discret pourrais-tu faire cette semaine ?$t$,texte_officiel=$t$Jésus enseigne de donner en secret : « ton Père, qui voit dans le secret, te le rendra » (Matthieu 6:4). Le livre raconte une enveloppe reçue un soir, d'un homme qui ne s'est jamais fait connaître, au moment exact d'un besoin caché. Cette semaine, essaie un geste discret : une aide, un service, un mot, sans photo ni annonce. Tu n'as pas à le raconter.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 108–110.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=50 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : un cœur plus libre$t$,principe=$t$Faire le point sur l'argent, la gratitude et le partage.$t$,theme=$t$Qu'est-ce qui a changé dans ton regard sur l'argent cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé des signes d'attachement à l'argent, de la gratitude, des mains ouvertes, de la simplicité et du partage. Relis tes moments de gratitude et ce que tu as pu donner, en argent, en temps ou en attention. Il n'y a pas de bonne quantité. Remarque seulement si ton regard sur l'argent et sur les autres a un peu changé.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitres 4 et 5 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=51 and numero_message=1;
update seneve.contents set titre=$t$Le temps et la présence sont des dons$t$,principe=$t$Donner autre chose que de l'argent.$t$,theme=$t$À qui pourrais-tu offrir une heure de présence cette semaine ?$t$,texte_officiel=$t$Le livre répond à l'objection « je n'ai pas d'argent à donner » : « Le temps est une monnaie. La présence est une monnaie. Les compétences sont une monnaie. » Une veuve a besoin qu'on l'écoute ; un jeune a besoin qu'on lui apprenne un métier ; un malade isolé attend un visage. Choisis une personne et offre-lui un peu de ton temps cette semaine.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 110–112.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=52 and numero_message=1;
update seneve.contents set titre=$t$Fidèle dans ce qui est à autrui$t$,principe=$t$Prendre soin de ce qui ne nous appartient pas.$t$,theme=$t$Qu'est-ce qui t'a été confié et mérite plus de soin ?$t$,texte_officiel=$t$Le chapitre 6 suit Joseph dans la maison de Potiphar : il gère les biens d'un autre avec soin. Jésus dit : « Si vous n'avez pas été fidèles dans ce qui est à autrui, qui vous donnera ce qui est à vous ? » (Luc 16:12). Ce qui est à autrui, c'est aussi le temps de ton employeur, l'outil prêté, la parole donnée. Aujourd'hui, rends un objet, respecte un horaire ou tiens une promesse faite à quelqu'un.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 119–120.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=53 and numero_message=1;
update seneve.contents set titre=$t$Remarquer les visages tristes$t$,principe=$t$Être attentif à une personne de son entourage.$t$,theme=$t$Qui, autour de toi, semble porter quelque chose de lourd en ce moment ?$t$,texte_officiel=$t$En prison, Joseph remarque que deux codétenus ont mauvaise mine et leur demande : « Pourquoi avez-vous mauvais visage aujourd'hui ? » (Genèse 40:7). Le livre souligne que cette petite attention a changé son histoire. La fidélité concerne aussi les personnes : un collègue fatigué, une voisine seule, un proche préoccupé. Aujourd'hui, prends le temps de demander sincèrement des nouvelles à quelqu'un.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 124–125.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=54 and numero_message=1;
update seneve.contents set titre=$t$Savoir où va son argent$t$,principe=$t$Observer ses dépenses sans les juger.$t$,theme=$t$Quelle dépense aimerais-tu mieux comprendre ce mois-ci ?$t$,texte_officiel=$t$Le livre propose un exercice : pendant trente jours, ne rien changer, mais noter chaque dépense. Beaucoup y découvrent des « fuites invisibles », comme les petits achats impulsifs. Le chapitre 6 rappelle aussi l'exemple de Joseph, qui fit mettre de côté une part des récoltes pendant les années d'abondance (Genèse 41:34). Si tu le souhaites, commence aujourd'hui un carnet personnel. Il reste à toi : SÉNEVÉ ne te demande pas tes montants.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 126–128.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=55 and numero_message=1;
update seneve.contents set titre=$t$Commencer par le silence$t$,principe=$t$Créer un temps de calme avant les écrans.$t$,theme=$t$Qu'est-ce qui remplit le premier quart d'heure de tes journées ?$t$,texte_officiel=$t$Le chapitre 7 rappelle que Dieu n'était ni dans le vent, ni dans le tremblement de terre, ni dans le feu, mais dans « une voix douce et tranquille » (1 Rois 19). Le livre conseille de commencer la journée par dix à vingt minutes de silence devant Dieu, avant le téléphone. Demain matin, essaie de ne pas regarder ton téléphone avant ta prière.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 135–136.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=56 and numero_message=1;
update seneve.contents set titre=$t$Ralentir quand l'urgence monte$t$,principe=$t$Reconnaître la pression qui pousse à décider trop vite.$t$,theme=$t$Quelle décision mérite que tu prennes plus de temps ?$t$,texte_officiel=$t$Le livre distingue deux voix : l'urgence pousse, l'Esprit conduit ; l'urgence crée de l'anxiété, l'Esprit donne la paix. L'auteur raconte comment des contrats signés sous pression ont contribué à ses propres dettes. Il en a tiré une règle : quand la pression de décider immédiatement devient forte, c'est le signal de ralentir, de prier et de consulter. Pense à une décision qui te presse en ce moment.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 137–140.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=57 and numero_message=1;
update seneve.contents set titre=$t$Relire quatre semaines$t$,principe=$t$Regarder le chemin parcouru pendant le mois.$t$,theme=$t$Quelle partie de ce mois t'a le plus parlé ?$t$,texte_officiel=$t$Ce mois a traversé tout le livre : Dieu premier, la dîme et l'offrande, le travail, l'argent, le partage, la fidélité et la conduite de l'Esprit. Relis tes bilans de semaine. Remarque ce que tu as compris, ce que tu as commencé, et ce qui reste difficile. Le chemin n'est pas une course : reprendre après une pause fait aussi partie de la fidélité.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, conclusion générale, pages imprimées 149–150 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=58 and numero_message=1;
update seneve.contents set titre=$t$Cinq questions avant de décider$t$,principe=$t$Se donner des repères pour une décision importante.$t$,theme=$t$Quelle question t'aiderait le plus dans une décision que tu prépares ?$t$,texte_officiel=$t$Le livre propose cinq questions avant une décision importante. Ai-je une paix durable ? Ce choix est-il cohérent avec la Parole ? Y a-t-il des confirmations que je n'ai pas provoquées ? Qu'en disent des personnes mûres et compétentes ? Et si je retire le gain financier, ferais-je le même choix ? Garde ces questions près de toi pour ta prochaine décision importante.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 142–143.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=59 and numero_message=1;
update seneve.contents set titre=$t$Choisir une clé pour la suite$t$,principe=$t$Faire un bilan paisible et choisir un seul pas.$t$,theme=$t$Quelle clé veux-tu choisir pour le mois prochain ?$t$,texte_officiel=$t$À la fin du livre, l'auteur invite à choisir « une clé — une seule pour commencer ». Parmi les sept repères de ce mois, lequel veux-tu pratiquer en priorité le mois prochain ? Ton bilan ne mesure ni ta foi ni ta valeur ; il t'aide à voir où tu en es. Tes habitudes quotidiennes continuent, et tu peux adapter tes horaires à tout moment.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, conclusion générale, pages imprimées 150–151.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=60 and numero_message=1;
update seneve.programme_versions set valide_par=valide_par||' ; mois 2 (jours 31 à 60) validé le 27/10/2026'
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and valide_par not like '%mois 2%';
